                (3.0, 0.9, 0.12), (3.25, 0.7, 0.08), (3.5, 0.8, 0.12), (3.75, 0.7, 0.08),
                (4.0, 0.9, 0.12), (4.25, 0.7, 0.08), (4.5, 0.8, 0.12), (4.75, 0.7, 0.08),
