async def mcp_opendaw_set_transpose(semitones: int) -> str:
    """Set global transpose for the piano roll view (does not affect audio playback).

    semitones: Number of semitones to transpose (-48 to +48).

    Returns success with old and new values.
    """
    if semitones < -48 or semitones > 48:
        return json.dumps({"error": f"Transpose must be -48 to +48, got {semitones}"})
    result = await bridge.evaluate(f"""() => {{
        const h = window.DAW_HELPERS;
        try {{
            const pm = h.rootBoxAdapter.pianoMode;
            const old = pm.transpose.getValue();
            h.editing.modify(() => {{
                pm.transpose.field.setValue({semitones});
            }});
            return {{success: true, old_transpose: old, new_transpose: {semitones}}};
        }} catch(e) {{
            return {{error: e.message}};
        }}
    }}""")
    return _wrap_eval(result)


async def mcp_opendaw_set_vaporisateur_osc_param(osc_index: int, param_name: str, value: float, unit_index: int) -> str:
    """Set a parameter on a Vaporisateur oscillator.

osc_index: Oscillator index (0, 1).
param_name: One of: waveform, volume, octave, tune.
  waveform: 0=Sine, 1=Triangle, 2=Saw, 3=Square
  volume: dB (-Infinity to +6)
  octave: integer offset
  tune: semitone offset (float)
value: New value.
unit_index: Audio unit index (-1 = auto-detect).

Returns old and new values.
"""
    safe_param = param_name.replace('"', '').replace("'", '').replace('\\', '')
    result = await bridge.evaluate(f"""() => {{
        const h = window.DAW_HELPERS;
        const unitIdx = {unit_index};
        const oscIdx = {osc_index};
        const paramName = "{safe_param}";
        const newVal = {value};

        let vap = null;
        if (unitIdx >= 0) {{
            const units = h.allAUBoxes();
            if (unitIdx >= units.length) return {{error: "No audio unit at index " + unitIdx}};
            const au = units[unitIdx];
            const incoming = h.inputBoxes(au);
            vap = incoming.find(b => b.constructor.name === "VaporisateurDeviceBox");
        }} else {{
            const units = h.allAUBoxes();
            for (const au of units) {{
                const incoming = h.inputBoxes(au);
                vap = incoming.find(b => b.constructor.name === "VaporisateurDeviceBox");
                if (vap) break;
            }}
        }}
        if (!vap) return {{error: "No Vaporisateur found"}};

        const oscFields = vap.oscillators.fields();
        if (oscIdx >= oscFields.length) return {{error: "No oscillator at index " + oscIdx}};
        const osc = oscFields[oscIdx];

        // Map param name to field index
        const paramMap = {{
            waveform: 1,
            volume: 2,
            octave: 3,
            tune: 4,
        }};
        const fieldIdx = paramMap[paramName];
        if (fieldIdx === undefined) return {{error: "Unknown param: " + paramName + ". Valid: waveform, volume, octave, tune"}};

        const field = osc.getField(fieldIdx);
        const oldValue = field.getValue();
        h.modify(() => {{
            field.setValue(newVal);
        }});

        return {{
            success: true,
            osc_index: oscIdx,
            param: paramName,
            old_value: oldValue,
            new_value: field.getValue(),
        }};
    }}""")
    return _wrap_eval(result)


async def mcp_opendaw_shift_mode(
    unit_index: int = -1,
    track_index: int = -1,
    region_index: int = -1,
    root_note: str = "C",
    from_scale: str = "minor",
    to_scale: str = "dorian",
    preserve_root: bool = True,
) -> str:
    """Transform notes from one scale/mode to another, keeping the tonic.

    Finds which scale degrees differ between from_scale and to_scale, then
    shifts ONLY the notes on those degrees by the interval difference. The
    tonic (degree 1) and unchanged degrees stay put — the transformation is
    surgical, not a blanket snap.

    Examples:
      shift_mode(root_note="A", from_scale="minor", to_scale="dorian")
        → minor 6th (Ab) becomes major 6th (F#). A minor → A dorian.
          Only notes on degree 6 shift (+1 semitone). Everything else stays.
      shift_mode(root_note="E", from_scale="minor", to_scale="phrygian")
        → degree 2 (F#) becomes F natural (-1 semitone). E minor → E phrygian.
      shift_mode(root_note="D", from_scale="major", to_scale="mixolydian")
        → degree 7 (C#) becomes C natural (-1 semitone). D major → D mixolydian.
      shift_mode(root_note="C", from_scale="minor", to_scale="harmonic_minor")
        → degree 7 (Bb) becomes B natural (+1 semitone). C minor → C harmonic minor.

    Unlike force_scale_notes (snaps to nearest scale tone — can change
    the melodic shape), shift_mode preserves the contour: notes that are
    already in the target scale don't move. Only the specific degrees that
    differ between the two scales are shifted.

    Unlike reharmonize_progression (works on chord symbols), shift_mode
    works on individual notes in a region.

    Args:
        unit_index: AU index (-1 = all AUs).
        track_index: Note track index (-1 = all note tracks).
        region_index: Region index (-1 = all regions on track).
        root_note: Tonic note (C, C#, D, ...). Stays the same for both scales.
        from_scale: Source scale name.
        to_scale: Target scale name.
        preserve_root: If True (default), never shift the tonic pitch class.
            If False, allow tonic to shift (rare, only for non-modal transformations).

    Returns per-note shift details: which pitch classes moved, by how much,
    and total notes affected.
    """
    from opendaw_mcp.music_theory import SCALE_INTERVALS

    note_to_num = {"C": 0, "C#": 1, "D": 2, "D#": 3, "E": 4, "F": 5,
                   "F#": 6, "G": 7, "G#": 8, "A": 9, "A#": 10, "B": 11}
    root_num = note_to_num.get(root_note)
    if root_num is None:
        return f"Error: invalid root_note '{root_note}'"
    from_intervals = SCALE_INTERVALS.get(from_scale)
    if from_intervals is None:
        return f"Error: unknown from_scale '{from_scale}'. Available: {list(SCALE_INTERVALS.keys())}"
    to_intervals = SCALE_INTERVALS.get(to_scale)
    if to_intervals is None:
        return f"Error: unknown to_scale '{to_scale}'. Available: {list(SCALE_INTERVALS.keys())}"

    if from_scale == to_scale:
        return f"Error: from_scale and to_scale are the same ('{from_scale}') — nothing to shift"

    # Build pitch class → scale degree mapping for both scales
    # For each pitch class 0-11, determine which degree it is in each scale
    # Then find which degrees differ and compute the shift
    from_pc_to_degree = {}
    for iv in from_intervals:
        pc = (root_num + iv) % 12
        from_pc_to_degree[pc] = from_pc_to_degree.get(pc, len(from_intervals))

    to_pc_to_degree = {}
    for iv in to_intervals:
        pc = (root_num + iv) % 12
        to_pc_to_degree[pc] = to_pc_to_degree.get(pc, len(to_intervals))

    # Build the shift map: for each pitch class, what's the shift amount?
    # A note at pitch class P belongs to from_scale degree D_from.
    # In to_scale, degree D_from maps to a different interval.
    # We need to find: for each from_scale degree, what's the to_scale
    # interval at the same degree position?

    # Build sorted interval arrays aligned by degree index
    from_sorted = sorted(from_intervals)
    to_sorted = sorted(to_intervals)

    # Map: pitch class -> shift amount (semitones)
    shift_map = {}  # pc -> semitone shift

    max_degrees = max(len(from_sorted), len(to_sorted))
    for i in range(max_degrees):
        if i >= len(from_sorted) or i >= len(to_sorted):
            continue
        from_iv = from_sorted[i]
        to_iv = to_sorted[i]
        if from_iv != to_iv:
            from_pc = (root_num + from_iv) % 12
            shift = to_iv - from_iv
            if preserve_root and from_pc == root_num:
                continue
            shift_map[from_pc] = shift

    # Handle scales with different lengths (e.g. pentatonic vs heptatonic)
    # If to_scale has MORE degrees than from_scale, notes that don't exist
    # in from_scale but do in to_scale should be left alone (they're already
    # in the target). If to_scale has FEWER degrees, notes on extra degrees
    # in from_scale need to be shifted to the nearest target degree.
    if len(from_sorted) > len(to_sorted):
        # from_scale has more notes — extra degrees need to snap
        for i in range(len(to_sorted), len(from_sorted)):
            from_iv = from_sorted[i]
            from_pc = (root_num + from_iv) % 12
            # Find nearest to_scale pitch class
            best_pc = None
            best_dist = 999
            for to_iv in to_sorted:
                to_pc = (root_num + to_iv) % 12
                dist = min(abs(from_pc - to_pc), 12 - abs(from_pc - to_pc))
                if dist < best_dist:
                    best_dist = dist
                    best_pc = to_pc
            if best_pc is not None and best_pc != from_pc:
                shift = (best_pc - from_pc + 6) % 12 - 6  # shortest path
                if shift != 0:
                    shift_map[from_pc] = shift

    shift_map_json = json.dumps({str(k): v for k, v in shift_map.items()})
    _ = (shift_map_json, root_num)

    result = await bridge.evaluate(f"""async () => {{
        const h = window.DAW_HELPERS;
        const shiftMap = {shift_map_json};
        const rootPc = {root_num};

        const allUnits = h.allAUBoxes();
        const unitIndices = {unit_index} < 0
            ? allUnits.map((_, i) => i)
            : [{unit_index}];

        let totalShifted = 0;
        const shiftDetails = [];
        const pcCounts = {{}};

        for (const unitIdx of unitIndices) {{
            if (unitIdx < 0 || unitIdx >= allUnits.length) continue;
            const au = allUnits[unitIdx];
            const noteTracks = h.noteTrackBoxes(au);
            const trackIndices = {track_index} < 0
                ? noteTracks.map((_, i) => i)
                : [{track_index}];

            for (const trackIdx of trackIndices) {{
                if (trackIdx < 0 || trackIdx >= noteTracks.length) continue;
                const trackBox = noteTracks[trackIdx];
                const regions = h.regionBoxes(trackBox);
                const regionIndices = {region_index} < 0
                    ? regions.map((_, i) => i)
                    : [{region_index}];

                for (const regIdx of regionIndices) {{
                    if (regIdx < 0 || regIdx >= regions.length) continue;
                    const region = regions[regIdx];
                    let collection = null;
                    try {{
                        const vertex = region.events.targetVertex.unwrap();
                        collection = vertex.box || vertex;
                    }} catch(e) {{ continue; }}
                    if (!collection || !collection.events) continue;

                    const notes = h.eventBoxes(collection);

                    h.modify(() => {{
                        for (const n of notes) {{
                            const pitch = n.pitch.getValue();
                            const pc = ((pitch % 12) + 12) % 12;
                            const pcKey = String(pc);
                            if (pcKey in shiftMap) {{
                                const shift = shiftMap[pcKey];
                                const newPitch = pitch + shift;
                                n.pitch.setValue(newPitch);
                                totalShifted++;
                                pcCounts[pcKey] = (pcCounts[pcKey] || 0) + 1;
                            }}
                        }}
                    }});
                }}
            }}
        }}

        const shiftSummary = Object.entries(shiftMap).map(([pc, shift]) => ({{
            pitch_class: parseInt(pc),
            shift_semitones: shift,
            notes_affected: pcCounts[pc] || 0,
        }}));

        return {{
            success: true,
            root_note: "{root_note}",
            from_scale: "{from_scale}",
            to_scale: "{to_scale}",
            preserve_root: {str(preserve_root).lower()},
            total_notes_shifted: totalShifted,
            degrees_changed: Object.keys(shiftMap).length,
            shift_map: shiftSummary,
        }};
    }}""")
    return _wrap_eval(result)


async def mcp_opendaw_spread_voicing(
    unit_index: int,
    track_index: int,
    region_index: int,
    chord_position: float,
    mode: str = "open",
    spread_octaves: int = 1,
) -> str:
    """Spread or compact a chord voicing — open vs close harmony.

    Transforms the spacing between chord tones at a specific beat position.
    Close voicing (all notes within one octave) sounds tight and focused.
    Open voicing (notes spread across multiple octaves) sounds wide and
    spacious — the hallmark of jazz piano, film score strings, and
    orchestral arrangements.

    mode: "open" — move every other note up by spread_octaves octaves.
      This creates drop-2/drop-3 style open voicings from close chords.
      The lowest note stays, the next goes up an octave, the next stays,
      etc. Result: wider intervallic spacing, more airy sound.
    mode: "close" — collapse all chord tones into the lowest possible
      octave (within 12 semitones from the lowest note). Compresses
      spread voicings back to close harmony. Useful for tight block
      chords after open passages.
    mode: "drop2" — drop the second-highest note down an octave.
      Classic jazz piano voicing technique. Creates the quintessential
      "comping" sound.
    mode: "drop3" — drop the third-highest note down an octave.
      Another standard jazz voicing, slightly wider than drop2.

    chord_position: Beat position where the chord starts (finds all
      notes at this position, groups them as a chord).
    spread_octaves: For "open" mode — how many octaves to spread (1-3,
      default 1). 1 = subtle widening, 2 = very open, 3 = extreme.

    Returns original pitches, new pitches, mode used, chord size.

    Example:
      # Open up a close triad for jazz piano sound
      spread_voicing(0, 2, 0, 4.0, mode="open")
      # Classic drop-2 jazz voicing
      spread_voicing(0, 2, 0, 4.0, mode="drop2")
    """
    valid_modes = ("open", "close", "drop2", "drop3")
    if mode not in valid_modes:
        return f'{{"error": "mode must be one of {list(valid_modes)}, got {mode}"}}'
    if not (1 <= spread_octaves <= 3):
        return f'{{"error": "spread_octaves must be 1-3, got {spread_octaves}"}}'

    result = await bridge.evaluate(f"""async () => {{
        const h = window.DAW_HELPERS;
        const unitIdx = {unit_index};
        const trackIdx = {track_index};
        const regionIdx = {region_index};
        const beatPos = {chord_position};
        const mode = "{mode}";
        const spreadOct = {spread_octaves};

        const region = h.region(unitIdx, trackIdx, regionIdx);
        if (region.isEmpty?.()) return {{error: "region not found"}};
        const reg = region.unwrap?.() || region;
        const eventsField = reg.events.targetVertex.unwrap();
        const collBox = eventsField.box;
        const noteEvents = [...collBox.events.pointerHub.incoming()];

        const Quarter = h.ppqn.Quarter;
        const targetTicks = Math.round(beatPos * Quarter);

        // Find notes at this position
        const chordNotes = noteEvents
            .filter(n => n.box.position.getValue() === targetTicks)
            .sort((a, b) => a.box.pitch.getValue() - b.box.pitch.getValue());

        if (chordNotes.length < 2) return {{error: "need at least 2 notes at beat position for voicing spread"}};

        const originalPitches = chordNotes.map(n => n.box.pitch.getValue());

        h.modify(() => {{
            if (mode === "open") {{
                // Move every other note (starting from 2nd lowest) up by spread_octaves
                for (let i = 1; i < chordNotes.length; i += 2) {{
                    const newPitch = chordNotes[i].box.pitch.getValue() + 12 * spreadOct;
                    chordNotes[i].box.pitch.setValue(Math.min(127, newPitch));
                }}
            }} else if (mode === "close") {{
                // Collapse all notes to within one octave of lowest
                const lowest = chordNotes[0].box.pitch.getValue();
                for (let i = 1; i < chordNotes.length; i++) {{
                    let p = chordNotes[i].box.pitch.getValue();
                    while (p >= lowest + 12) p -= 12;
                    chordNotes[i].box.pitch.setValue(p);
                }}
                // Re-sort by pitch after collapsing
                const sorted = chordNotes.slice().sort((a, b) => a.box.pitch.getValue() - b.box.pitch.getValue());
                // Ensure ascending order maintained
            }} else if (mode === "drop2") {{
                // Drop 2nd highest note down an octave
                if (chordNotes.length >= 2) {{
                    const idx = chordNotes.length - 2;
                    const newPitch = chordNotes[idx].box.pitch.getValue() - 12;
                    chordNotes[idx].box.pitch.setValue(Math.max(0, newPitch));
                }}
            }} else if (mode === "drop3") {{
                // Drop 3rd highest note down an octave
                if (chordNotes.length >= 3) {{
                    const idx = chordNotes.length - 3;
                    const newPitch = chordNotes[idx].box.pitch.getValue() - 12;
                    chordNotes[idx].box.pitch.setValue(Math.max(0, newPitch));
                }}
            }}
        }});

        const newPitches = chordNotes.map(n => n.box.pitch.getValue());

        return {{
            mode: mode,
            chord_position: beatPos,
            chord_size: chordNotes.length,
            original_pitches: originalPitches,
            new_pitches: newPitches,
            spread_octaves: spreadOct,
            next_step: "use create_voice_led_progression for smooth voicing transitions between chords",
        }};
    }}""")
    return _wrap_eval(result)


async def mcp_opendaw_start_engine() -> str:
    """Start the audio engine (AudioWorklet) after setting up tracks and regions.

Call this AFTER loading audio, creating tracks, and placing regions —
but BEFORE playback or effects. The engine serializes the current project
state into the AudioWorklet processor, so all boxes must exist first.
"""
    result = await bridge.evaluate("""() => {
        return new Promise(async (resolve) => {
            try {
                // DAW_engineStarted is a function on creative-studio (returns bool),
                // a plain boolean on the repo test_host (engine auto-started).
                const started = typeof window.DAW_engineStarted === 'function'
                    ? window.DAW_engineStarted()
                    : !!window.DAW_engineStarted;
                if (started) {
                    resolve({success: true, message: "Engine already started"});
                    return;
                }
                if (typeof window.DAW_startEngine !== 'function') {
                    resolve({error: "DAW_startEngine not available and engine not started"});
                    return;
                }
                await window.DAW_startEngine();
                resolve({success: true, message: "Engine started"});
            } catch(e) {
                resolve({error: e.message, stack: e.stack?.slice(0, 300)});
            }
        });
    }""")
    return _wrap_eval(result)


async def mcp_opendaw_stop_browser() -> str:
    """Stop Playwright Chromium and release RAM (~2GB+ if engine was hot).

Call after render/export when the DAW session is done for a while.
Next tool that needs the page will relaunch via bridge.ensure/start.
Does NOT delete project state on disk — only kills the headless browser.
"""
    try:
        await bridge.stop()
        return _ok({"stopped": True, "message": "Playwright browser stopped; RAM released"})
    except Exception as e:
        return _err(str(e))


async def mcp_opendaw_swap_sections(
    section1_start: float,
    section1_end: float,
    section2_start: float,
    section2_end: float,
    unit_indices: str = "",
) -> str:
    """Swap two sections of the arrangement — exchange their positions on the timeline.

    Exchanges all note/audio content between two time ranges, moving
    section A to where section B was and vice versa. Useful for song
    structure experimentation: try chorus before verse, swap bridge
    with solo, reorder sections without manual cut/paste.

    Both sections can be different lengths — the swap preserves each
    section's content and shifts everything accordingly. If sections
    are adjacent, it's a simple swap. If there's a gap between them,
    the gap content stays in place.

    Args:
        section1_start: Start beat of first section
        section1_end: End beat of first section
        section2_start: Start beat of second section (must be > section1_end)
        section2_end: End beat of second section
        unit_indices: Comma-separated unit indices to process ("" = all units)

    Returns:
        JSON with sections_swapped, notes_moved per unit, section sizes.
    """
    s1_start = max(0.0, float(section1_start))
    s1_end = max(s1_start, float(section1_end))
    s2_start = max(s1_end, float(section2_start))
    s2_end = max(s2_start, float(section2_end))

    if s2_start <= s1_end:
        return '{"error": "section2 must start after section1 ends"}'

    result = await bridge.evaluate(f"""async () => {{
        const s1Start = {s1_start};
        const s1End = {s1_end};
        const s2Start = {s2_start};
        const s2End = {s2_end};
        const unitFilter = {json.dumps(unit_indices)};

        const h = window.DAW_HeadlessBridge;
        const PPQN = 960;
        const s1StartTick = Math.round(s1Start * PPQN);
        const s1EndTick = Math.round(s1End * PPQN);
        const s2StartTick = Math.round(s2Start * PPQN);
        const s2EndTick = Math.round(s2End * PPQN);
        const s1Len = s1EndTick - s1StartTick;
        const s2Len = s2EndTick - s2StartTick;

        const units = [...h.api.units.pointerHub.incoming()];
        const unitIdxs = unitFilter ? unitFilter.split(',').map(n => parseInt(n.trim())) : units.map((_, i) => i);

        let totalNotesSwapped = 0;
        const unitStats = [];

        for (const unitIdx of unitIdxs) {{
            if (unitIdx >= units.length) continue;
            const au = units[unitIdx];
            let unitNotesSwapped = 0;

            // Process note tracks
            const tracks = [...au.tracks.pointerHub.incoming()];
            for (const track of tracks) {{
                const trackBox = track.box;
                const isNote = trackBox.type && (trackBox.type.label === 'note' || trackBox.type.value === 2);
                if (!isNote) continue;

                const regions = [...track.regions.pointerHub.incoming()];
                for (const region of regions) {{
                    const regionBox = region.box;
                    const coll = regionBox.events.targetVertex.unwrap();
                    if (!coll) continue;
                    const notes = [...coll.events.pointerHub.incoming()];

                    // Collect notes in each section
                    const s1Notes = [];
                    const s2Notes = [];
                    const otherNotes = [];

                    for (const note of notes) {{
                        const nb = note.box;
                        const pos = nb.position.value;
                        if (pos >= s1StartTick && pos < s1EndTick) {{
                            s1Notes.push({{note, pos, pitch: nb.pitch.value, dur: nb.duration.value, vel: nb.velocity.value, cent: nb.cent ? nb.cent.value : 0}});
                        }} else if (pos >= s2StartTick && pos < s2EndTick) {{
                            s2Notes.push({{note, pos, pitch: nb.pitch.value, dur: nb.duration.value, vel: nb.velocity.value, cent: nb.cent ? nb.cent.value : 0}});
                        }} else {{
                            otherNotes.push(note);
                        }}
                    }}

                    if (s1Notes.length === 0 && s2Notes.length === 0) continue;

                    const NoteEventBox = window.DAW_NoteEventBox;
                    if (!NoteEventBox) continue;

                    await h.editing.modify(async () => {{
                        // Delete original section notes
                        for (const item of s1Notes) item.note.delete();
                        for (const item of s2Notes) item.note.delete();

                        // Re-create s1 notes at s2 position (offset = s2Start - s1Start)
                        const offset1to2 = s2StartTick - s1StartTick;
                        for (const item of s1Notes) {{
                            const newPos = item.pos + offset1to2;
                            NoteEventBox.create(h.boxGraph, h.uuid.generate(), (box) => {{
                                box.pitch.setValue(item.pitch);
                                box.position.setValue(newPos);
                                box.duration.setValue(item.dur);
                                box.velocity.setValue(item.vel);
                                if (item.cent) box.cent.setValue(item.cent);
                                box.events.refer(coll.events);
                            }});
                            unitNotesSwapped++;
                        }}

                        // Re-create s2 notes at s1 position (offset = s1Start - s2Start)
                        const offset2to1 = s1StartTick - s2StartTick;
                        for (const item of s2Notes) {{
                            const newPos = item.pos + offset2to1;
                            NoteEventBox.create(h.boxGraph, h.uuid.generate(), (box) => {{
                                box.pitch.setValue(item.pitch);
                                box.position.setValue(newPos);
                                box.duration.setValue(item.dur);
                                box.velocity.setValue(item.vel);
                                if (item.cent) box.cent.setValue(item.cent);
                                box.events.refer(coll.events);
                            }});
                            unitNotesSwapped++;
                        }}
                    }});
                }}
            }}

            totalNotesSwapped += unitNotesSwapped;
            unitStats.push({{unit: unitIdx, notes_swapped: unitNotesSwapped}});
        }}

        return JSON.stringify({{
            sections_swapped: true,
            section1: {{start: s1Start, end: s1End, length_beats: s1End - s1Start}},
            section2: {{start: s2Start, end: s2End, length_beats: s2End - s2Start}},
            notes_moved: totalNotesSwapped,
            unit_stats: unitStats,
        }});
    }}""")
    return _wrap_eval(result)


async def mcp_opendaw_switch_phase(phase: str) -> str:
    """Switch the active tool phase for phase-based tool loading.

    When OPENDAW_MCP_MODE=phase, only tools for the active phase are registered.
    This reduces the tool schema payload by showing only relevant tools.

    Phases:
    - **inspect**: read-only — project state, list tracks/regions/effects, meters, analysis
    - **compose**: create — tracks, instruments, notes, regions, sections, arrangements, chords, melodies
    - **mix**: effects — add/configure effects, sends, buses, mixing, mastering, genre effects, automation
    - **render**: output — render, export, audio I/O, time/pitch stretch, presets

    Meta-tools (evaluate_raw, get_full_project_state, switch_phase) are always available.

    phase: inspect | compose | mix | render

    Example:
      switch_phase("compose")  # activate composition tools
      switch_phase("mix")      # switch to mixing tools
    """
    valid = list(PHASE_TOOLS.keys())
    if phase not in valid:
        return json.dumps({"error": f"Invalid phase. Valid: {valid}"})

    _apply_phase(phase)
    return json.dumps({
        "phase": phase,
        "tools_active": len(PHASE_TOOLS[phase]) + len(ALL_PHASE_TOOLS),
        "available_phases": valid,
        "note": f"Switched to {phase} phase. {len(PHASE_TOOLS[phase])} tools now active.",
    })


def main():
    """Entry point for opendaw-mcp command."""
    import sys
    if len(sys.argv) > 1:
        if sys.argv[1] in ("--version", "-v"):
            mode = os.environ.get("OPENDAW_MCP_MODE", "full")
            print(f"opendaw-mcp {__version__} — {len(LITE_TOOLS) if mode == 'lite' else '504'} MCP tools (mode: {mode})")
            return
        if sys.argv[1] in ("--list-tools", "-l"):
            import asyncio
            tools = asyncio.run(mcp.list_tools())
            for t in sorted(tools, key=lambda x: x.name):
                print(f"  {t.name} — {t.description[:80]}")
            print(f"\nTotal: {len(tools)} tools (mode: {os.environ.get('OPENDAW_MCP_MODE', 'full')})")
            return
        if sys.argv[1] in ("--help", "-h"):
            print("opendaw-mcp — MCP tools for agent-native openDAW control")
            print()
            print("Usage:")
            print("  opendaw-mcp              Start MCP server (stdio, full mode, 505 tools)")
            print("  OPENDAW_MCP_MODE=lite opendaw-mcp  39 essential tools (92% token savings)")
            print("  OPENDAW_MCP_MODE=phase opendaw-mcp  Phase-based: switch_phase to load subset")
            print("  MCP_TRANSPORT=sse opendaw-mcp  Start MCP server (SSE transport)")
            print("  opendaw-mcp --version    Show version")
            print("  opendaw-mcp --list-tools List all registered MCP tools")
            print("  opendaw-mcp --help       Show this help")
            print()
            print("Environment variables:")
            print("  OPENDAW_MCP_MODE     Tool set: full (default, 505), lite (39), or phase (switch_phase)")
            print("  OPENDAW_MCP_OUTPUT_LIMIT  Max chars per tool response (0=unlimited, e.g. 2000)")
            print("  OPENDAW_HOST_DIR   Path to headless openDAW directory")
            print("  OPENDAW_URL        URL of openDAW Vite dev server")
            print("  OPENDAW_EXPORT_DIR Directory for audio exports")
            print("  NODE_BIN_DIR       Path to Node.js bin directory")
            print("  MCP_TRANSPORT      Transport type: stdio (default) or sse")
            print("  FASTMCP_HOST       SSE host (default 0.0.0.0)")
            print("  FASTMCP_PORT       SSE port (default 8080)")
            return

    # Lite mode: remove non-essential tools
    mode = os.environ.get("OPENDAW_MCP_MODE", "full")
    if mode == "lite":
        import asyncio
        all_tools = asyncio.run(mcp.list_tools())
        lite_set = LITE_TOOLS
        removed = 0
        for t in all_tools:
            if t.name not in lite_set:
                mcp._tool_manager.remove_tool(t.name)
                removed += 1
        print(f"Lite mode: {len(all_tools) - removed} tools active, {removed} removed", file=sys.stderr)
    elif mode == "phase":
        # Phase mode: start with compose phase, agent calls switch_phase to change
        _apply_phase("compose")
        print(f"Phase mode: compose phase active ({len(PHASE_TOOLS['compose'])} tools). Call switch_phase to change.", file=sys.stderr)

    transport = os.environ.get("MCP_TRANSPORT", "stdio")
    mcp.run(transport=transport)


async def mcp_opendaw_validate_project() -> str:
    """Check if the project is valid — detects overlapping regions on the same track.

    Returns valid (bool) and details about any issues found.
    """
    result = await bridge.evaluate("""() => {
        const h = window.DAW_HELPERS;
        let valid = true;
        let issues = [];
        try {
            valid = !h.project.invalid();
        } catch(e) {
            issues.push("validation error: " + e.message);
        }
        if (!valid) {
            const units = h.allAUBoxes();
            for (const au of units) {
                const tracks = h.trackBoxes(au);
                for (const track of tracks) {
                    const regions = h.regionBoxes(track)
                        .sort((a, b) => a.position.getValue() - b.position.getValue());
                    for (let i = 1; i < regions.length; i++) {
                        const prevEnd = regions[i-1].position.getValue() + regions[i-1].duration.getValue();
                        if (prevEnd > regions[i].position.getValue()) {
                            issues.push("overlap on track: " + (track.label?.getValue?.() || 'unnamed') +
                                " region " + (i-1) + " and " + i);
                        }
                    }
                }
            }
        }
        return {valid: valid, issues: issues};
    }""")
    return _wrap_eval(result)


async def mcp_opendaw_wait_for_condition(condition_js: str, timeout_ms: int = 10000, poll_interval_ms: int = 500) -> str:
    """Wait for a JavaScript condition to evaluate to true in the DAW context.

    Polls the condition at regular intervals until it returns true or timeout is reached.

    condition_js: JavaScript expression that returns a truthy value when the condition is met.
    timeout_ms: Maximum wait time in milliseconds (default 10000).
    poll_interval_ms: Polling interval in milliseconds (default 500).
    """
    import asyncio
    if bridge.page is None:
        await bridge.start()
    elapsed = 0
    while elapsed < timeout_ms:
        result = await bridge.page.evaluate(f"""() => {{
            try {{ return Boolean({condition_js}); }}
            catch(e) {{ return false; }}
        }}""")
        if result:
            return _ok({"elapsed_ms": elapsed, "condition_met": True})
        await asyncio.sleep(poll_interval_ms / 1000)
        elapsed += poll_interval_ms
    return json.dumps({"success": False, "condition_met": False, "elapsed_ms": elapsed, "timeout_ms": timeout_ms})

